-- Link pages, 5 October 2026: Martin's page as he edited it in the local preview (before he could sign in to the
-- live editor): group pictures, colours, the diary and the Volunteer note. Replaces his items once; click counts are
-- kept, since they're stored by address and the links keep theirs. Uploaded pictures stay local (no bucket yet).
DELETE FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR REPLACE INTO lp_node_dark (node_id, linked, icon, tint, zoom) SELECT id, 0, 'amybo-dark', 'mono', 1 FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND slug = 'amybo' AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR REPLACE INTO lp_node_meta (node_id, tint, zoom, day, highlight) SELECT id, 'mono', 1, '', 0 FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND slug = 'amybo-youtube' AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR REPLACE INTO lp_node_meta (node_id, tint, zoom, day, highlight) SELECT id, '#ff932e', 1, '', 0 FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND slug = 'music' AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR REPLACE INTO lp_node_meta (node_id, tint, zoom, day, highlight) SELECT id, '#fbff00', 1, '', 0 FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND slug = 'wishlist' AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR REPLACE INTO lp_node_meta (node_id, tint, zoom, day, highlight) SELECT id, '', 1, '261003', 0 FROM lp_nodes WHERE person_id = (SELECT id FROM lp_people WHERE handle = 'martin') AND slug = 'amybo-website' AND NOT EXISTS (SELECT 1 FROM lp_seeds WHERE name = 'martin-page-v2');
INSERT OR IGNORE INTO lp_seeds (name) VALUES ('martin-page-v2');
